#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash execution and human confirmation
"""

import os
import sys
import subprocess
import json
from typing import Dict, Any, List, Optional
from anthropic import Anthropic

class BashTool:
    """Tool for executing bash commands with user confirmation"""

    @staticmethod
    def execute(command: str, require_confirmation: bool = True) -> Dict[str, Any]:
        """Execute a bash command with optional user confirmation"""
        if require_confirmation:
            print(f"\n🔧 Tool wants to execute command:")
            print(f"  $ {command}")
            response = input("\nAllow execution? (y/n): ").strip().lower()
            if response != 'y':
                return {
                    "success": False,
                    "output": "Command execution denied by user",
                    "error": None
                }

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
            return {
                "success": result.returncode == 0,
                "output": result.stdout,
                "error": result.stderr if result.stderr else None
            }
        except subprocess.TimeoutExpired:
            return {
                "success": False,
                "output": None,
                "error": "Command timed out after 30 seconds"
            }
        except Exception as e:
            return {
                "success": False,
                "output": None,
                "error": str(e)
            }

class AgentLoop:
    """Minimal agentic loop with Anthropic API"""

    def __init__(self, api_key: Optional[str] = None):
        self.client = Anthropic(api_key=api_key or os.environ.get("ANTHROPIC_API_KEY"))
        self.messages: List[Dict[str, str]] = []
        self.bash_tool = BashTool()

        # Tool definition for Claude
        self.tools = [
            {
                "name": "run_bash",
                "description": "Execute a bash command. User confirmation required.",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "command": {
                            "type": "string",
                            "description": "The bash command to execute"
                        }
                    },
                    "required": ["command"]
                }
            }
        ]

    def process_tool_calls(self, tool_calls: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process tool calls from Claude"""
        results = []

        for tool_call in tool_calls:
            if tool_call["name"] == "run_bash":
                command = tool_call["input"]["command"]
                result = self.bash_tool.execute(command)
                results.append({
                    "tool_call_id": tool_call["id"],
                    "result": result
                })

        return results

    def run(self, initial_prompt: str, max_turns: int = 10):
        """Run the agent loop"""
        print(f"🤖 Starting agent with prompt: {initial_prompt}\n")

        # Initial user message
        self.messages.append({"role": "user", "content": initial_prompt})

        for turn in range(max_turns):
            print(f"\n--- Turn {turn + 1} ---")

            # Get Claude's response
            response = self.client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                messages=self.messages,
                tools=self.tools
            )

            # Add assistant response to history
            self.messages.append({
                "role": "assistant", 
                "content": response.content
            })

            # Check if Claude wants to use tools
            tool_calls = []
            for content in response.content:
                if content.type == "tool_use":
                    tool_calls.append({
                        "id": content.id,
                        "name": content.name,
                        "input": content.input
                    })

            if not tool_calls:
                # No tools called, display response and check if task complete
                print(f"\n🤖 Assistant: {response.content[0].text}")

                # Ask if task is complete
                continue_response = input("\nContinue? (y/n): ").strip().lower()
                if continue_response != 'y':
                    break

                # Get next user input
                user_input = input("\nYour message: ").strip()
                if user_input:
                    self.messages.append({"role": "user", "content": user_input})
                else:
                    break
            else:
                # Process tool calls
                print(f"\n🤖 Assistant wants to use tools...")
                if response.content[0].type == "text" and response.content[0].text:
                    print(f"Reasoning: {response.content[0].text}")

                tool_results = self.process_tool_calls(tool_calls)

                # Add tool results to messages
